# Attack predicates, relative to the board start after S|.
def attack_terms(target, attacker):
    tr, tf = target
    result = []
    if attacker == 'black':
        pawn_row, pawn_char = tr - 1, 'p'
        knight_char, king_char = 'n', 'k'
        bishop_chars, rook_chars = '[bq]', '[rq]'
    else:
        pawn_row, pawn_char = tr + 1, 'P'
        knight_char, king_char = 'N', 'K'
        bishop_chars, rook_chars = '[BQ]', '[RQ]'
    if 0 <= pawn_row < 8:
        for af in (tf - 1, tf + 1):
            if 0 <= af < 8:
                result.append(((pawn_row, af), pawn_char, []))
    for dr, df in knight_steps:
        rr, ff = tr + dr, tf + df
        if 0 <= rr < 8 and 0 <= ff < 8:
            result.append(((rr, ff), knight_char, []))
    for dr, df in king_steps:
        rr, ff = tr + dr, tf + df
        if 0 <= rr < 8 and 0 <= ff < 8:
            result.append(((rr, ff), king_char, []))
    for dr, df in slide_dirs['Q']:
        rr, ff = tr + dr, tf + df
        between = []
        while 0 <= rr < 8 and 0 <= ff < 8:
            chars = bishop_chars if dr and df else rook_chars
            result.append(((rr, ff), chars, list(between)))
            between.append((rr, ff))
            rr += dr
            ff += df
    return result

def attack_conditions(target, attacker='black'):
    result = []
    for square, chars, between in attack_terms(target, attacker):
        result.append(
            r'(?=.{%d}%s)' % (off(*square), chars) +
            ''.join(r'(?=.{%d}\.)' % off(*x) for x in between)
        )
    return result

def no_attack_assertions(targets):
    return ''.join('(?!%s)' % cond for target in targets for cond in attack_conditions(target))

def virtual_white_attack_conditions(target, vacant, occupied):
    result = []
    vacant = set(vacant)
    for square, chars, between in attack_terms(target, 'white'):
        requirements = [(square, chars)] + [(x, r'\.') for x in between]
        pieces = []
        impossible = False
        for required_square, required_chars in requirements:
            if required_square in vacant:
                if required_chars != r'\.':
                    impossible = True
                continue
            if required_square in occupied:
                impossible = True
                continue
            pieces.append(r'(?=.{%d}%s)' % (off(*required_square), required_chars))
        if not impossible:
            result.append(''.join(pieces))
    return result

